      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"34\">BUILD TRUST THIS WEEK</text><text x=\"550\" y=\"95\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Five moves for your next meeting</text><rect x=\"150\" y=\"150\" width=\"800\" height=\"80\" rx=\"20\" fill=\"#6366f1\" fill-opacity=\"0.15\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"200\" y=\"200\" text-anchor=\"start\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"20\">1.</text><text x=\"240\" y=\"200\" text-anchor=\"start\" fill=\"#ffffff\" font-size=\"18\">Run a personal-history round</text><rect x=\"150\" y=\"245\" width=\"800\" height=\"80\" rx=\"20\" fill=\"#8b5cf6\" fill-opacity=\"0.15\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"200\" y=\"295\" text-anchor=\"start\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"20\">2.</text><text x=\"240\" y=\"295\" text-anchor=\"start\" fill=\"#ffffff\" font-size=\"18\">Go first with something real</text><rect x=\"150\" y=\"340\" width=\"800\" height=\"80\" rx=\"20\" fill=\"#10b981\" fill-opacity=\"0.15\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"200\" y=\"390\" text-anchor=\"start\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"20\">3.</text><text x=\"240\" y=\"390\" text-anchor=\"start\" fill=\"#ffffff\" font-size=\"18\">Add a shared behavioral tool</text><rect x=\"150\" y=\"435\" width=\"800\" height=\"80\" rx=\"20\" fill=\"#f59e0b\" fill-opacity=\"0.15\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"200\" y=\"485\" text-anchor=\"start\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"20\">4.</text><text x=\"240\" y=\"485\" text-anchor=\"start\" fill=\"#ffffff\" font-size=\"18\">Name the norm out loud</text><rect x=\"150\" y=\"530\" width=\"800\" height=\"80\" rx=\"20\" fill=\"#ec4899\" fill-opacity=\"0.15\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"200\" y=\"580\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"20\">5.</text><text x=\"240\" y=\"580\" text-anchor=\"start\" fill=\"#ffffff\" font-size=\"18\">Follow up with the discloser</text></svg>",
